/bin/bash -lc "python - <<'PY'
import json
d=json.load(open('canonical-input.json'))
p={g['id']:g for g in d['preparation']}
for gid in d['candidate']['requires']:
 print(json.dumps(p[gid],indent=2, ensure_ascii=False))
 for s in p[gid]['requires']:
  print(p[s]['title'],p[s]['requires'])
print(\"Changed fields by equality\", [(k,d['original'][k]==d['candidate'][k]) for k in d['original']]); print([(k,d['original']['examData'][k]==d['candidate']['examData'][k]) for k in d['original']['examData']])
PY"

